with
quarantined as (
    select
        chrono_row_uid,
        chrono_vehicle_code,
        vehicle_display_name,
        vehicle_group_name,
        vehicle_form,
        manager_master_code,
        manager_name_text,
        manager_lei,
        legal_entity_identifier,
        vendor_crosswalk_id,
        private_market_bucket,
        investment_style,
        launch_year,
        commitment_amount_usd,
        reporting_ccy,
        domicile_iso2,
        lifecycle_state,
        snapshot_date,
        violation_00,
        violation_01
    from {{ ref("investment__chrono_fund__checked") }}
),
violations as (
    select
        'chrono_row_uid_not_null' as rule_name,
        chrono_row_uid,
        chrono_vehicle_code,
        vehicle_display_name,
        vehicle_group_name,
        vehicle_form,
        manager_master_code,
        manager_name_text,
        manager_lei,
        legal_entity_identifier,
        vendor_crosswalk_id,
        private_market_bucket,
        investment_style,
        launch_year,
        commitment_amount_usd,
        reporting_ccy,
        domicile_iso2,
        lifecycle_state,
        snapshot_date
    from quarantined
    where violation_00

    union all

    select
        'vehicle_display_name_not_null' as rule_name,
        chrono_row_uid,
        chrono_vehicle_code,
        vehicle_display_name,
        vehicle_group_name,
        vehicle_form,
        manager_master_code,
        manager_name_text,
        manager_lei,
        legal_entity_identifier,
        vendor_crosswalk_id,
        private_market_bucket,
        investment_style,
        launch_year,
        commitment_amount_usd,
        reporting_ccy,
        domicile_iso2,
        lifecycle_state,
        snapshot_date
    from quarantined
    where violation_01
)

select
    rule_name,
    chrono_row_uid,
    chrono_vehicle_code,
    vehicle_display_name,
    vehicle_group_name,
    vehicle_form,
    manager_master_code,
    manager_name_text,
    manager_lei,
    legal_entity_identifier,
    vendor_crosswalk_id,
    private_market_bucket,
